effect.shader:
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmSnowLayer(vec2 uv, float cols, float speed, float wind, float sizePx, float soft, float seed, float t, float aspect, float gate){
vec2 p = uv * vec2(cols, cols / max(aspect * 1.4, 0.6));
vec2 cell = floor(p);
float h = gmHash2(cell + seed);
if (h < gate) return 0.0;
vec2 f = fract(p) - 0.5;
float h2 = gmHash2(cell * 2.7 + seed * 3.3);
float h3 = gmHash2(cell * 5.1 + seed * 7.7);
float sway = sin(t * (0.6 + h2) + h * 6.2831) * 0.5 + sin(t * 1.7 + h3 * 9.0) * 0.22;
vec2 off = f - vec2(sway * 0.32 + wind * 0.22, fract(-t * speed * (0.5 + h2)));
off.x = off.x - floor(off.x + 0.5);
float d = length(off * vec2(1.0, aspect));
float rad = (0.05 + 0.16 * h3) * sizePx;
float flake = (1.0 - smoothstep(rad * (1.0 - soft * 0.6), rad, d));
flake *= smoothstep(0.0, 0.18, fall) * smoothstep(1.0, 0.82, fall);
return flake;
}
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float aspect = max(getTexSize(inputImg.size).x / max(getTexSize(inputImg.size).y, 1.0), 0.5);
float gate = 1.0 - snowAmount * 0.01;
float sz = flakeSize;
float s1 = gmSnowLayer(uv, 26.0, fallSpeed * 0.55, windDrift, sz * 0.7, flakeSoft, 11.0, acTime, aspect, gate);
float s2 = gmSnowLayer(uv, 17.0, fallSpeed * 0.8, windDrift * 1.3, sz, flakeSoft, 23.0, acTime, aspect, gate);
float s3 = gmSnowLayer(uv, 11.0, fallSpeed * 1.1, windDrift * 1.7, sz * 1.6, flakeSoft * 0.8, 37.0, acTime, aspect, gate);
float snow = (s1 * 0.55 + s2 * 0.8 + s3 * 1.0) * snowBright;
float sp = 0.0;
if (sparkle) {
float tw = sin(acTime * 7.0 + uv.x * 340.0 + uv.y * 410.0);
sp = max(tw - 0.985, 0.0) * 60.0 * snow;
}
vec3 col = src.rgb * src.a + snowTint.rgb * min(snow + sp, 2.0) * src.a;
gl_FragColor = vec4(col, src.a);
}
